import { index, pgTable, primaryKey, text, timestamp, uuid } from 'drizzle-orm/pg-core';

/**
 * Aira messages table -- idempotent message sync from Aira clients.
 */
export const airaMessages = pgTable(
  'aira_messages',
  {
    // Anonymous per-install UUID generated by the Aira mobile app. Intentionally
    // NOT a foreign key to users(id): these ids never correspond to real accounts,
    // so an FK (or validating against users) would reject every insert. Writes are
    // gated by the shared AIRA_SYNC_SECRET; spoofing within that boundary is
    // accepted for analytics-grade data.
    userId: uuid('user_id').notNull(),
    clientId: text('client_id').notNull(),
    role: text('role').notNull(),
    text: text('text').notNull(),
    source: text('source'),
    imageKey: text('image_key'),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull(),
    insertedAt: timestamp('inserted_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.userId, table.clientId] }),
    index('aira_messages_user_id_created_at_idx').on(table.userId, table.createdAt),
  ],
);

export type AiraMessage = typeof airaMessages.$inferSelect;
export type NewAiraMessage = typeof airaMessages.$inferInsert;
